import re, os
def strip_comments(s):
    out=[]; i=0; depth=0
    while i < len(s):
        if depth==0 and s.startswith('/-',i): depth=1; i+=2; continue
        if depth>0:
            if s.startswith('/-',i): depth+=1; i+=2; continue
            if s.startswith('-/',i): depth-=1; i+=2; continue
            out.append('\n' if s[i]=='\n' else ' '); i+=1; continue
        if s.startswith('--',i):
            j=s.find('\n',i); j=len(s) if j<0 else j
            out.append(' '*(j-i)); i=j; continue
        out.append(s[i]); i+=1
    return ''.join(out)
pat=re.compile(r'\bBundle\b')
for root,ds,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if not f.endswith('.lean'): continue
        p=os.path.join(root,f)
        src=strip_comments(open(p).read())
        for i,l in enumerate(src.split('\n'),1):
            if pat.search(l): print(f"{p}:{i}: {l.strip()[:130]}")
